int reversePairs(int[] nums) {
    int count = 0;
    for (int i = 0; i < nums.length; i++) {
        for (int j = i + 1; j < nums.length; j++) {
            if ((long) nums[i] > 2L * nums[j]) count++;   // 2 * nums[j] can overflow an int
        }
    }
    return count;
}

