int sortCount(int lo, int hi) {                   // sorts a[lo..hi), returns the reverse pairs inside it
    if (hi - lo <= 1) return 0;
    int mid = (lo + hi) >>> 1;
    int count = sortCount(lo, mid) + sortCount(mid, hi);
    int j = mid;
    for (int i = lo; i < mid; i++) {              // both halves are sorted: j only moves forward
        while (j < hi && (long) a[i] > 2L * a[j]) j++;
        count += j - mid;                         // a[mid..j) are all small enough for a[i]
    }
    int[] merged = new int[hi - lo];
    int p = lo, q = mid, k = 0;
    while (p < mid && q < hi) merged[k++] = a[p] <= a[q] ? a[p++] : a[q++];
    while (p < mid) merged[k++] = a[p++];
    while (q < hi) merged[k++] = a[q++];
    System.arraycopy(merged, 0, a, lo, merged.length);
    return count;
}

int sortCount(vector<int>& a, int lo, int hi) {   // sorts a[lo..hi), returns the reverse pairs inside it
    if (hi - lo <= 1) return 0;
    int mid = (lo + hi) / 2;
    int count = sortCount(a, lo, mid) + sortCount(a, mid, hi);
    int j = mid;
    for (int i = lo; i < mid; i++) {              // both halves are sorted: j only moves forward
        while (j < hi && (long long)a[i] > 2LL * a[j]) j++;
        count += j - mid;                         // a[mid..j) are all small enough for a[i]
    }
    inplace_merge(a.begin() + lo, a.begin() + mid, a.begin() + hi);   // the usual merge
    return count;
}

int reversePairs(vector<int>& nums) {
    vector<int> a = nums;
    return sortCount(a, 0, a.size());
